    static long[][] patterns() {
        java.util.List<long[]> out = new java.util.ArrayList<>();

        long[] empty = new long[64];
        out.add(empty);

        long[] full = new long[64];
        java.util.Arrays.fill(full, ~0L);
        out.add(full);

        long[] single = new long[64];
        single[0] = 1L;
        out.add(single);

        long[] slab = new long[64];
        java.util.Arrays.fill(slab, 0, 32, ~0L);
        out.add(slab);

        long[] checker = new long[64];
        for (int i = 0; i < 64; i++) {
            checker[i] = (i % 2 == 0) ? 0xAAAAAAAAAAAAAAAAL : 0x5555555555555555L;
        }
        out.add(checker);

        long[] repeated = new long[64];
        for (int i = 0; i < 64; i++) {
            repeated[i] = 0x0000FFFF0000FFFFL;
        }
        out.add(repeated);

        long[] columns = new long[64];
        for (int i = 0; i < 64; i++) {
            columns[i] = 0x0800080008000800L;
        }
        out.add(columns);

        for (long seed : new long[]{1L, 42L, 0xCE17L, 987654321L}) {
            Random random = new Random(seed);
            long[] dense = new long[64];
            for (int i = 0; i < 64; i++) {
                dense[i] = random.nextLong();
            }
            out.add(dense);

            Random sparseRandom = new Random(seed ^ 0x5EEDL);
            long[] sparse = new long[64];
            for (int i = 0; i < 64; i++) {
                sparse[i] = sparseRandom.nextLong() & sparseRandom.nextLong() & sparseRandom.nextLong();
            }
            out.add(sparse);
        }

        return out.toArray(new long[0][]);
    }

    @Test
    void boxSequencesMatchTheBoxedSortBaseline() {
        long[][] patterns = patterns();
        assertEquals(EXPECTED.length, patterns.length);

        for (int p = 0; p < patterns.length; p++) {
            BoxFinder finder = new BoxFinder(new AreaFinder());
            finder.findBoxes(patterns[p], 0);

            int[] expected = EXPECTED[p];
            assertEquals(expected.length, finder.boxes.size(), "pattern " + p + " box count");
            for (int i = 0; i < expected.length; i++) {
                assertEquals(expected[i], finder.boxes.getInt(i), "pattern " + p + " box " + i);
            }
        }
    }
